#include <iostream>
#include <iterator>
#include <string_view>

int main() {
    constexpr std::string_view str_view("abcd");
    constexpr auto end = str_view.end();
    constexpr auto cend = str_view.cend();

    static_assert(*std::prev(end) == 'd' && 'd' == *std::prev(cend) and end == cend);
}
